MERGE INTO CDR_PATIENTBASICINFO t USING (
SELECT #{item.PatientID, jdbcType=VARCHAR} AS PatientID, #{item.AuthorOrganization, jdbcType=VARCHAR} AS AuthorOrganization, #{item.AuthorOrganizationName, jdbcType=VARCHAR} AS AuthorOrganizationName, #{item.HealthRecordId, jdbcType=VARCHAR} AS HealthRecordId, #{item.IdCard, jdbcType=VARCHAR} AS IdCard, #{item.IdCardCode, jdbcType=VARCHAR} AS IdCardCode, #{item.HealthCardId, jdbcType=VARCHAR} AS HealthCardId, #{item.MedicalInsuranceCategoryCode, jdbcType=VARCHAR} AS MedicalInsuranceCategoryCode, #{item.HealthInsuranceCardId, jdbcType=VARCHAR} AS HealthInsuranceCardId, #{item.SelfPaidCardId, jdbcType=VARCHAR} AS SelfPaidCardId, #{item.Name, jdbcType=VARCHAR} AS Name, #{item.Sex, jdbcType=VARCHAR} AS Sex, TO_DATE(#{item.BirthDate, jdbcType=DATE}, 'YYYY-MM-DD HH24:MI:SS') AS BirthDate, #{item.MaritalStatus, jdbcType=VARCHAR} AS MaritalStatus, #{item.Nationality, jdbcType=VARCHAR} AS Nationality, #{item.EthnicGroup, jdbcType=VARCHAR} AS EthnicGroup, #{item.OccupationCategoryCode, jdbcType=VARCHAR} AS OccupationCategoryCode, #{item.PatientPhone, jdbcType=VARCHAR} AS PatientPhone, #{item.WorkUnit, jdbcType=VARCHAR} AS WorkUnit, #{item.WorkAddrPhone, jdbcType=VARCHAR} AS WorkAddrPhone, TO_DATE(#{item.SystemTime, jdbcType=DATE}, 'YYYY-MM-DD HH24:MI:SS') AS SystemTime, #{item.Author, jdbcType=VARCHAR} AS Author, #{item.PrivacySign, jdbcType=CHAR} AS PrivacySign, #{item.SourcePatientId, jdbcType=VARCHAR} AS SourcePatientId, #{item.SourcePatientIdType, jdbcType=VARCHAR} AS SourcePatientIdType, #{item.AddrTypeCode, jdbcType=VARCHAR} AS AddrTypeCode, #{item.AddrTypeName, jdbcType=VARCHAR} AS AddrTypeName, #{item.Address, jdbcType=VARCHAR} AS Address, #{item.Province, jdbcType=VARCHAR} AS Province, #{item.City, jdbcType=VARCHAR} AS City, #{item.County, jdbcType=VARCHAR} AS County, #{item.Town, jdbcType=VARCHAR} AS Town, #{item.Village, jdbcType=VARCHAR} AS Village, #{item.HouseNumber, jdbcType=VARCHAR} AS HouseNumber, #{item.PostalCode, jdbcType=VARCHAR} AS PostalCode, #{item.RelationShipWithPatient, jdbcType=VARCHAR} AS RelationShipWithPatient, #{item.ContactPerson, jdbcType=VARCHAR} AS ContactPerson, #{item.ContactPersonTel, jdbcType=VARCHAR} AS ContactPersonTel, #{item.ContactIdCard, jdbcType=VARCHAR} AS ContactIdCard, #{item.ContactIdCardCode, jdbcType=VARCHAR} AS ContactIdCardCode, TO_DATE(#{item.TimeStamp, jdbcType=DATE}, 'YYYY-MM-DD HH24:MI:SS') AS TimeStamp, #{item.OperationType, jdbcType=DECIMAL} AS OperationType, #{item.CardType, jdbcType=VARCHAR} AS CardType, #{item.IssuingRegion, jdbcType=VARCHAR} AS IssuingRegion, #{item.ModifyFlag, jdbcType=DECIMAL} AS ModifyFlag, #{item.JRCSDM, jdbcType=VARCHAR} AS JRCSDM FROM DUAL
) s ON (t.PatientID = s.PatientID) WHEN NOT MATCHED THEN INSERT ( PatientID, AuthorOrganization, AuthorOrganizationName, HealthRecordId, IdCard, IdCardCode, HealthCardId, MedicalInsuranceCategoryCode, HealthInsuranceCardId, SelfPaidCardId, Name, Sex, BirthDate, MaritalStatus, Nationality, EthnicGroup, OccupationCategoryCode, PatientPhone, WorkUnit, WorkAddrPhone, SystemTime, Author, PrivacySign, SourcePatientId, SourcePatientIdType, AddrTypeCode, AddrTypeName, Address, Province, City, County, Town, Village, HouseNumber, PostalCode, RelationShipWithPatient, ContactPerson, ContactPersonTel, ContactIdCard, ContactIdCardCode, TimeStamp, OperationType, CardType, IssuingRegion, ModifyFlag, JRCSDM ) VALUES ( s.PatientID, s.AuthorOrganization, s.AuthorOrganizationName, s.HealthRecordId, s.IdCard, s.IdCardCode, s.HealthCardId, s.MedicalInsuranceCategoryCode, s.HealthInsuranceCardId, s.SelfPaidCardId, s.Name, s.Sex, s.BirthDate, s.MaritalStatus, s.Nationality, s.EthnicGroup, s.OccupationCategoryCode, s.PatientPhone, s.WorkUnit, s.WorkAddrPhone, s.SystemTime, s.Author, s.PrivacySign, s.SourcePatientId, s.SourcePatientIdType, s.AddrTypeCode, s.AddrTypeName, s.Address, s.Province, s.City, s.County, s.Town, s.Village, s.HouseNumber, s.PostalCode, s.RelationShipWithPatient, s.ContactPerson, s.ContactPersonTel, s.ContactIdCard, s.ContactIdCardCode, s.TimeStamp, s.OperationType, s.CardType, s.IssuingRegion, s.ModifyFlag, s.JRCSDM )
